// StatsMessage are observed counters for a node or an edge.
// They are counters: they never move a graph's revision.
type StatsMessage struct {
	// Count is how many times it ran.
	Count int64 `json:"count"`
	// Errors is how many of those failed.
	Errors int64 `json:"errors"`
	// LastAt is when it last ran.
	LastAt *time.Time `json:"lastAt,omitempty"`
	// AvgMs is the mean duration in milliseconds.
	AvgMs float64 `json:"avgMs"`
	// MaxMs is the longest duration in milliseconds.
	MaxMs float64 `json:"maxMs"`
}

// DiagnosticMessage is a problem found while building the graph.
// It names the node or the file it is about, and how serious it is.
type DiagnosticMessage struct {
	// Severity is "error" or "warning". An error refuses to start the app.
	Severity string `json:"severity"`
	// Message says what is wrong and how to fix it, in English.
	Message string `json:"message"`
	// Texts is the message in each language kit speaks, by language: "en",
	// "fr". The Studio shows its reader's.
	Texts map[string]string `json:"texts,omitempty"`
	// Node is the node concerned, when there is one.
	Node string `json:"node,omitempty"`
	// Source is where the problem is.
	Source *SourceMessage `json:"source,omitempty"`
}

// AnalysisResult reports the status of static analysis.
// It says whether the analyzer ran, how long it took, and the error that
// stopped it.
type AnalysisResult struct {
	// Status is "pending", "running", "ok", "failed" or "unavailable".
	Status string `json:"status"`
	// Error explains a failed or unavailable analysis.
	Error string `json:"error,omitempty"`
	// At is when the analysis finished.
	At *time.Time `json:"at,omitempty"`
	// Packages is how many packages were analyzed.
	Packages int `json:"packages,omitempty"`
	// TookMs is how long it took.
	TookMs float64 `json:"tookMs,omitempty"`
}

// ModuleMessage is a module the app mounts: a Go module's services, released and
// mounted together like a bundle (ADR 0008). Everything a module declares is
// qualified with its name: its services are "<module>.<service>" — the one
// named like the module is "<module>" —, so its nodes are
// "<module>.<service>/<kind>/<name>" and carry [NodeEntity.Module].
type ModuleMessage struct {
	// Name is the name kit.NewModule gives it.
	Name string `json:"name"`
	// Doc is its description in the product's default language; Docs the
	// same in other languages, by tag, as a node's.
	Doc  string            `json:"doc,omitempty"`
	Docs map[string]string `json:"docs,omitempty"`
	// Package is the Go package that declares it: the one a product imports.
	Package string `json:"package,omitempty"`
	// Build is the Go module it comes from, and its version.
	Build *ModuleVersionMessage `json:"build,omitempty"`
	// Services are its services' IDs, in the order it lists them.
	Services []string `json:"services"`
	// Requires are the modules it requires (kit.Requires), by name.
	Requires []string `json:"requires,omitempty"`
	// RequiredBy are the mounted modules that require it, by name, sorted.
	RequiredBy []string `json:"requiredBy,omitempty"`
	// Prefix is where its routes are served: "/<name>/" unless the mount
	// says otherwise (kit.Prefix); "/" shares the product's route space.
	Prefix string `json:"prefix"`
	// Source is where kit.NewModule declares it.
	Source *SourceMessage `json:"source,omitempty"`
	// Mount is where the app mounts it — App.With or kit.Mount —; absent
	// when only another module's kit.Requires mounted it, at its defaults.
	Mount *SourceMessage `json:"mount,omitempty"`
}

// FileMessage is one file a graph points at: its path, relative to its root — the
// product's module, or the Go module [SourceMessage.GoModule] names.
type FileMessage struct {
	// GoModule is empty for a file of the product's own module.
	GoModule string `json:"goModule,omitempty"`
	File     string `json:"file"`
}

// NodeEntity is one building block.
// Its ID is its identity; exactly one of the kind-specific fields matching
// Kind is set.
type NodeEntity struct {
	// ID is "<service>/<kind>/<name>", "<service>" for a service,
	// "binary:<name>" for a binary, "binary:<binary>/role/<name>" for a
	// role, "library:<name>" for a library, or [ExternalID]: the grammar of
	// [IDValue].
	ID string `json:"id"`
	// Kind says which building block this is.
	Kind NodeKind `json:"kind"`
	// Name is unique among the nodes of one kind in one service.
	Name string `json:"name"`
	// Service is the owning service ID. Empty for services and external.
	Service string `json:"service,omitempty"`
	// Module is the module the node belongs to — a module's service and
	// every node of it —; empty for the product's own.
	Module string `json:"module,omitempty"`
	// Doc is the Go doc comment of the declaration or of its handler, in
	// the product's default language.
	Doc string `json:"doc,omitempty"`
	// Docs are the same description in other languages, by tag ("fr"),
	// from the comment's tagged paragraphs: see [SplitDoc].
	Docs map[string]string `json:"docs,omitempty"`
	// Source is where the node is declared.
	Source *SourceMessage `json:"source,omitempty"`
	// Handler is the body of the function the node runs, when it has one.
	Handler      *SourceMessage    `json:"handler,omitempty"`
	Endpoint     *EndpointSpec     `json:"endpoint,omitempty"`
	Store        *StoreSpec        `json:"store,omitempty"`
	Topic        *TopicSpec        `json:"topic,omitempty"`
	Subscription *SubscriptionSpec `json:"subscription,omitempty"`
	Workflow     *WorkflowSpec     `json:"workflow,omitempty"`
	Job          *JobSpec          `json:"job,omitempty"`
	Frontend     *FrontendSpec     `json:"frontend,omitempty"`
	Auth         *AuthSpec         `json:"auth,omitempty"`
	Mailer       *MailerSpec       `json:"mailer,omitempty"`
	Loop         *LoopSpec         `json:"loop,omitempty"`
	Secret       *SecretSpec       `json:"secret,omitempty"`
	Port         *PortSpec         `json:"port,omitempty"`
	Command      *CommandSpec      `json:"command,omitempty"`
	Query        *QuerySpec        `json:"query,omitempty"`
	Binary       *BinarySpec       `json:"binary,omitempty"`
	Role         *RoleSpec         `json:"role,omitempty"`
	CLI          *CLISpec          `json:"cli,omitempty"`
	Listener     *ListenerSpec     `json:"listener,omitempty"`
	Library      *LibrarySpec      `json:"library,omitempty"`
	Presentation *PresentationSpec `json:"presentation,omitempty"`
	// Code is the code the node runs, as the static analysis read it: C4's
	// code level.
	Code *CodeResult `json:"code,omitempty"`
	// Stats are runtime counters, present on a runtime graph.
	Stats *StatsMessage `json:"stats,omitempty"`
}

// EndpointSpec describes an HTTP endpoint, or the implementation of a port.
// It carries the method and path, the request and response schemas, and its
// auth.
type EndpointSpec struct {
	// Method is the HTTP method, upper case; empty for an implementation.
	Method string `json:"method"`
	// Path is the route pattern, with {wildcards}; empty for an
	// implementation.
	Path string `json:"path"`
	// Expose is [ExposePublic] or [ExposePrivate].
	Expose string `json:"expose"`
	// Auth is [AuthRequired], [AuthOptional], or empty when the endpoint
	// ignores authentication.
	Auth string `json:"auth,omitempty"`
	// Request is the input type.
	Request *SchemaMessage `json:"request,omitempty"`
	// Response is the output type.
	Response *SchemaMessage `json:"response,omitempty"`
	// Pipeline lists the mechanics a request goes through before the
	// handler, in order.
	Pipeline []MechanicMessage `json:"pipeline,omitempty"`
	// Implements is the node ID of the port this endpoint implements
	// (Service.Implement): an endpoint with no route, reached through the
	// port.
	Implements string `json:"implements,omitempty"`
	// Exposes is the node ID of the command this endpoint dispatches, or of
	// the query it asks (Command.Expose, Query.Expose): its authentication
	// is the operation's, and the rest of its pipeline — validation, key,
	// authorization — the operation's own.
	Exposes string `json:"exposes,omitempty"`
	// Access is how an exposure says its operation is open on purpose —
	// [AccessAnyone] or [AccessAnyUser] —; empty when the operation says who
	// may run it (a permission, a rule), and on any other endpoint.
	Access string `json:"access,omitempty"`
}

// PortSpec describes a port: an operation a service needs and another
// implements.
type PortSpec struct {
	// Request is the type the port is called with.
	Request *SchemaMessage `json:"request,omitempty"`
	// Response is the type it answers.
	Response *SchemaMessage `json:"response,omitempty"`
	// Fallback is the node ID of the operation the port declares for when
	// the app binds nothing else (kit.Fallback).
	Fallback string `json:"fallback,omitempty"`
	// Bound is the node ID of the operation the port calls, as the start
	// chose it — on a static graph, as the analysis reads the same rule;
	// empty when nothing is bound or a test replaced the port. The graph
	// draws it as a declared edge from the port.
	Bound string `json:"bound,omitempty"`
	// Via is how it was chosen: one of the Via constants.
	Via string `json:"via,omitempty"`
}

// CommandSpec describes a command: an operation that changes something.
// It carries its input and result schemas, its handler, its queue and who may
// dispatch it.
type CommandSpec struct {
	// Input is the type it is dispatched with.
	Input *SchemaMessage `json:"input,omitempty"`
	// Result is the type it answers; Empty for a queued command.
	Result *SchemaMessage `json:"result,omitempty"`
	// Mode is [ModeSync] or [ModeQueued].
	Mode string `json:"mode"`
	// Auth is [AuthRequired] — implied by a permission —, [AuthOptional],
	// or empty when the command ignores authentication.
	Auth string `json:"auth,omitempty"`
	// Pipeline lists the mechanics a dispatch goes through before the
	// handler, in the order they run.
	Pipeline []MechanicMessage `json:"pipeline,omitempty"`
	// Permissions are the permissions a caller needs (Allow).
	Permissions []PermissionMessage `json:"permissions,omitempty"`
	// Authorize locates the function of its Authorize: a rule that needs
	// the data.
	Authorize *SourceMessage `json:"authorize,omitempty"`
	// Key is set when the command names the entity it is about (Key): two
	// runs with one key never overlap.
	Key bool `json:"key,omitempty"`
	// MaxDeliveries is how many attempts a queued command gets before it is
	// dead-lettered.
	MaxDeliveries int `json:"maxDeliveries,omitempty"`
	// Parallelism is how many dispatches of a queued command are handled at
	// once.
	Parallelism int `json:"parallelism,omitempty"`
	// Queue is "memory" or "file": where a queued command waits.
	Queue string `json:"queue,omitempty"`
	// DeadLetters is how many dispatches of a queued command were
	// abandoned, on a runtime graph.
	DeadLetters *int `json:"deadLetters,omitempty"`
}

// QuerySpec describes a query: an operation that reads and changes
// nothing.
type QuerySpec struct {
	// Input is the type it is asked with.
	Input *SchemaMessage `json:"input,omitempty"`
	// Result is the type it answers.
	Result *SchemaMessage `json:"result,omitempty"`
	// Auth is [AuthRequired] — implied by a permission —, [AuthOptional],
	// or empty when the query ignores authentication.
	Auth string `json:"auth,omitempty"`
	// Pipeline lists the mechanics a question goes through before the
	// handler, in the order they run.
	Pipeline []MechanicMessage `json:"pipeline,omitempty"`
	// Permissions are the permissions a caller needs (Allow).
	Permissions []PermissionMessage `json:"permissions,omitempty"`
	// Authorize locates the function of its Authorize: a rule that needs
	// the data.
	Authorize *SourceMessage `json:"authorize,omitempty"`
}

// PermissionMessage is what a caller needs to dispatch a command or to ask a
// query: that the app's policy lets it do Action to Resource (Allow).
type PermissionMessage struct {
	// Action is what the caller does: "place".
	Action string `json:"action"`
	// Resource is the kind of thing it does it to: "order".
	Resource string `json:"resource"`
}

// StoreSpec describes a store.
// It carries the entity's schema, its backend, its indexes, its privacy and
// its history.
type StoreSpec struct {
	// Entity is the stored type.
	Entity *SchemaMessage `json:"entity,omitempty"`
	// Backend is where the store's data is: "memory", "file", or the engine
	// of the database that keeps it (ADR 0004): "postgres", "mysql",
	// "sqlite".
	Backend string `json:"backend"`
	// Location is where a file backend keeps its data, relative to the data
	// directory.
	Location string `json:"location,omitempty"`
	// Database names the database that keeps the store, as the app declares
	// it (kit.Database, kit.Keeps) — present even while the store's data
	// stays in the data directory, in dev without the database's URL. Its
	// container is "container:database:<name>".
	Database string `json:"database,omitempty"`
	// Table is the table the database keeps the store's entities in —
	// "<service>__<store>", '-' and '.' written '_', a digest past the
	// engine's limit —, beside its index rows in "<table>___ix". Present
	// with Database.
	Table string `json:"table,omitempty"`
	// Count is how many entities the store holds, on a runtime graph.
	Count *int `json:"count,omitempty"`
	// Indexes are the secondary indexes the store maintains, in declaration
	// order.
	Indexes []IndexSpec `json:"indexes,omitempty"`
	// Privacy says what the store does with personal data (ADR 0006): whom
	// its records are about, why it keeps them and for how long. Absent when
	// its entity holds nothing personal and it declares no retention.
	Privacy *StorePrivacyMessage `json:"privacy,omitempty"`
	// History says what the store remembers of its records (ADR 0007): the
	// fields that keep their former values, its password policies. Absent
	// when it remembers nothing and has no policy.
	History *StoreHistoryMessage `json:"history,omitempty"`
	// ReadModel is set on a store derived from others (kit.ReadModel):
	// written by projections — subscriptions —, read by queries.
	ReadModel bool `json:"readModel,omitempty"`
}

// StorePrivacyMessage is what a store keeps of people: whom each record is about,
// why, for how long, and — on a runtime graph — what is held and due.
type StorePrivacyMessage struct {
	// Subject is the JSON pointer of the field that says whom each record is
	// about: "/email". Empty when the entity has no subject field.
	Subject string `json:"subject,omitempty"`
	// Purpose is why the store keeps its records, as kit.Purpose says it.
	Purpose string `json:"purpose,omitempty"`
	// Erase says when kit clears a record's personal data; Delete when it
	// removes the record.
	Erase  *RetentionSpec `json:"erase,omitempty"`
	Delete *RetentionSpec `json:"delete,omitempty"`
	// ByProduct is set when the product keeps the store's retention itself
	// (kit.RetentionByProduct): kit runs none — Erase and Delete are then
	// absent — and asks for neither a retention nor a subject.
	ByProduct *ProductRetentionSpec `json:"byProduct,omitempty"`
	// HeldUntil holds each record until an instant it carries: the law's
	// own retention (kit.HeldUntil).
	HeldUntil *HeldUntilSpec `json:"heldUntil,omitempty"`
	// Anonymise locates the function that says what an erased record keeps,
	// generalised (kit.Anonymise).
	Anonymise *SourceMessage `json:"anonymise,omitempty"`
	// DeleteOnErasure: a person's erasure deletes the record instead of
	// clearing it (kit.DeleteOnErasure).
	DeleteOnErasure bool `json:"deleteOnErasure,omitempty"`
	// Held is how many records a hold keeps, on a runtime graph.
	Held *int `json:"held,omitempty"`
	// Due is when the next record is due to be erased or deleted, on a
	// runtime graph; absent when none is.
	Due *time.Time `json:"due,omitempty"`
	// Erased and Deleted count what this run erased and deleted, on a
	// runtime graph.
	Erased  *int `json:"erased,omitempty"`
	Deleted *int `json:"deleted,omitempty"`
}

// ProductRetentionSpec is a retention the product keeps itself, as it says
// it.
type ProductRetentionSpec struct {
	// Limits says, in the product's words, how long the records keep their
	// personal data and how they go — the register's time limits, GDPR
	// art. 30(1)(f); empty when it gave none.
	Limits string `json:"limits,omitempty"`
}

// RetentionSpec is when kit erases or deletes a record: after a delay counted
// from an instant the record carries (After or Setting, and Since), or at an
// instant a function gives (At).
type RetentionSpec struct {
	// After is the delay, as a Go duration: the declared one, or the
	// setting's value when the graph describes a running app.
	After string `json:"after,omitempty"`
	// Setting names the setting of the store's service the delay is read
	// from, when the environment gives it.
	Setting string `json:"setting,omitempty"`
	// Since locates the function that gives the instant the delay counts
	// from: a record's closing, say.
	Since *SourceMessage `json:"since,omitempty"`
	// At locates the function that gives the instant itself.
	At *SourceMessage `json:"at,omitempty"`
}

// HeldUntilSpec is the hold a store declares on each of its records, until an
// instant the record carries.
type HeldUntilSpec struct {
	// At locates the function that gives the instant.
	At *SourceMessage `json:"at,omitempty"`
	// Reason is the legal ground the declaration gives: "commercial code:
	// 10 years".
	Reason string `json:"reason,omitempty"`
}

// IndexSpec is one secondary index of a store.
// Its name is unique in the store; Unique says whether two records may share
// a key.
type IndexSpec struct {
	// Name is how code asks for the index: Store.Lookup(ctx, name, key).
	Name string `json:"name"`
	// Unique is set when two entities may not share a key: a write that
	// would is refused with a conflict.
	Unique bool `json:"unique,omitempty"`
}

// TopicSpec describes a topic.
// It carries the message's schema; its subscriptions are the nodes it
// delivers to.
type TopicSpec struct {
	// Message is the published type.
	Message *SchemaMessage `json:"message,omitempty"`
	// Delivery is the guarantee: "at-least-once".
	Delivery string `json:"delivery"`
	// Broker is "memory" or "file".
	Broker string `json:"broker,omitempty"`
}

// SubscriptionSpec describes a subscription — or a watch (ADR 0008), a
// subscription whose deliveries come from stores instead of a topic.
type SubscriptionSpec struct {
	// Topic is the node ID of the consumed topic; empty for a watch.
	Topic string `json:"topic"`
	// Mark is what a watch hears the writes of: "personal", "special" or
	// "moderated", ADR 0006's marks. Empty for a subscription.
	Mark string `json:"mark,omitempty"`
	// OwnStores: the watch hears its own module's stores too — the
	// product's own, for a watch of the product's (kit.OwnStores) —, never
	// the writes its own handler makes.
	OwnStores bool `json:"ownStores,omitempty"`
	// Stores are the node IDs of the stores that feed a watch, sorted: those
	// whose entity holds a field with its mark, but its own module's — the
	// product's own, for a watch of the product's — unless OwnStores. Each
	// draws a declared delivers edge to it.
	Stores []string `json:"stores,omitempty"`
	// MaxDeliveries is how many attempts a message gets before it is
	// dead-lettered.
	MaxDeliveries int `json:"maxDeliveries,omitempty"`
	// Parallelism is how many messages are handled concurrently.
	Parallelism int `json:"parallelism,omitempty"`
	// DeadLetters is how many messages were abandoned, on a runtime graph.
	DeadLetters *int `json:"deadLetters,omitempty"`
}

// WorkflowSpec describes a state machine bound to a store.
// It carries the states and the transitions between them, and the store it
// lives in.
type WorkflowSpec struct {
	// Store is the node ID of the store holding the instances.
	Store string `json:"store"`
	// Field is the wire name of the entity field holding the state, when the
	// state function points at a field of the entity.
	Field string `json:"field,omitempty"`
	// Initial is the state a new instance enters.
	Initial string `json:"initial"`
	// States are in declaration order.
	States []StateSpec `json:"states"`
	// Transitions are in declaration order.
	Transitions []TransitionSpec `json:"transitions"`
}

// StateSpec is one state of a workflow.
// Terminal marks a state an instance stays in; Count is how many instances
// are in it.
type StateSpec struct {
	// Name is the state value, as text.
	Name string `json:"name"`
	// Terminal is set when no transition leaves the state.
	Terminal bool `json:"terminal,omitempty"`
	// Count is how many instances are in the state, on a runtime graph.
	Count *int `json:"count,omitempty"`
	// OnEnter lists the hooks run when an instance enters the state.
	OnEnter []SourceMessage `json:"onEnter,omitempty"`
}

// TransitionSpec is one arrow of a workflow.
// It names the event that fires it and the states it goes from and to.
type TransitionSpec struct {
	// Event names the transition. Timer and guard transitions have one too.
	Event string `json:"event"`
	// From is the source state.
	From string `json:"from"`
	// To is the target state.
	To string `json:"to"`
	// Trigger is [TriggerEvent], [TriggerTimer] or [TriggerGuard].
	Trigger string `json:"trigger"`
	// After is the delay of a timer transition, as a Go duration string.
	After string `json:"after,omitempty"`
	// Setting names the setting of the service the delay is read from, when
	// the environment gives it: "archive-after".
	Setting string `json:"setting,omitempty"`
	// At locates the function that says when a timer transition declared at
	// an instant is due — a due date, a deadline the entity carries.
	At *SourceMessage `json:"at,omitempty"`
	// Guard locates the condition of a guard transition.
	Guard *SourceMessage `json:"guard,omitempty"`
	// Source is where the transition is declared.
	Source *SourceMessage `json:"source,omitempty"`
	// Callers are the node IDs found to fire this event.
	Callers []string `json:"callers,omitempty"`
}

// JobSpec describes a scheduled job.
// It carries the fixed interval or the cron expression that schedules it.
type JobSpec struct {
	// Schedule is "every 10s" or a five-field cron expression.
	Schedule string `json:"schedule"`
	// Kind is "interval" or "cron".
	Kind string `json:"kind"`
}

// FrontendSpec describes static assets served by the product.
// It carries the path the assets are served under and where they are read
// from.
type FrontendSpec struct {
	// Prefix is the URL path the assets are served under.
	Prefix string `json:"prefix"`
	// Files is how many files are served.
	Files int `json:"files,omitempty"`
}

// AuthSpec describes the app's authentication handler.
// Credentials says what it reads from a request; Endpoints are the ones
// behind it.
type AuthSpec struct {
	// Credentials is the type the handler reads: its fields are tagged
	// cookie:"…" or header:"…".
	Credentials *SchemaMessage `json:"credentials,omitempty"`
	// Data is the type of what the handler says about the caller, which
	// endpoints read with kit.AuthData.
	Data *SchemaMessage `json:"data,omitempty"`
	// Endpoints counts the endpoints that ask for authentication.
	Endpoints int `json:"endpoints"`
}

// MailerSpec describes outbound mail.
// It carries the transport that empties the outbox and the outbox's counters.
type MailerSpec struct {
	// Transport is [TransportSMTP] or [TransportCapture].
	Transport string `json:"transport"`
	// Server is the relay's host:port. Credentials never appear.
	Server string `json:"server,omitempty"`
	// TLS is "starttls", "implicit" or "none", for SMTP.
	TLS string `json:"tls,omitempty"`
	// From is the default sender.
	From string `json:"from,omitempty"`
	// MaxAttempts is how many deliveries a message gets before it is
	// dead-lettered.
	MaxAttempts int `json:"maxAttempts"`
	// Outbox is "memory" or "file": where queued messages wait.
	Outbox string `json:"outbox,omitempty"`
	// Queued is how many messages wait in the outbox, on a runtime graph.
	Queued *int `json:"queued,omitempty"`
	// Sent is how many messages the transport accepted, on a runtime graph.
	Sent *int `json:"sent,omitempty"`
	// DeadLetters is how many messages were abandoned, on a runtime graph.
	DeadLetters *int `json:"deadLetters,omitempty"`
}

// SecretSpec describes a declared secret: how it is made, where it lives,
// its versions — never its value.
type SecretSpec struct {
	// Origin is [SecretProvided] or [SecretGenerated].
	Origin string `json:"origin"`
	// Variable is the environment variable that provides it, or — for a
	// generated secret — pins it: TODO_SMTP_URL, or TODO_SMTP_URL_FILE naming
	// a file.
	Variable string `json:"variable"`
	// Bytes is the size of each version of a generated secret.
	Bytes int `json:"bytes,omitempty"`
	// RotateEvery is how often kit makes a new version of a generated
	// secret, as a Go duration.
	RotateEvery string `json:"rotateEvery,omitempty"`
	// Keep is how many versions a rotation leaves, the new one included.
	Keep int `json:"keep,omitempty"`
	// Optional: a provided secret the product can do without
	// (kit.Optional) — found nowhere, it is absent, and the start goes on.
	Optional bool `json:"optional,omitempty"`
	// From is where the running app found it: one of the SecretFrom
	// constants, on a runtime graph. Empty when it is found nowhere — for an
	// optional secret, absent.
	From string `json:"from,omitempty"`
	// Version is the number of its current version, from 1.
	Version int `json:"version,omitempty"`
	// Created is when the current version was made; the environment does
	// not say when a variable was set.
	Created *time.Time `json:"created,omitempty"`
	// Versions is how many versions are kept.
	Versions int `json:"versions,omitempty"`
	// NextRotation is when kit rotates it next. Absent when kit does not
	// rotate it: provided, pinned by the environment, or in a store kit
	// cannot write.
	NextRotation *time.Time `json:"nextRotation,omitempty"`
	// Pinned: a generated secret the environment provides — kit uses it and
	// does not rotate it.
	Pinned bool `json:"pinned,omitempty"`
	// Rotations counts the rotations this process made.
	Rotations int `json:"rotations,omitempty"`
	// Problem says why it cannot be used, on a runtime graph.
	Problem string `json:"problem,omitempty"`
}

// LoopSpec describes a loop node.
// Style says whether it is declared (kit owns the wait) or hand-written.
type LoopSpec struct {
	// Style is [LoopDeclared] or [LoopGoroutine].
	Style string `json:"style"`
	// Wakes are what wakes a declared loop.
	Wakes []WakeSourceMessage `json:"wakes,omitempty"`
	// Selects are the cases of the select statements a hand-written loop
	// waits in, as the static analysis read them.
	Selects []SelectCaseMessage `json:"selects,omitempty"`
	// Restart is the supervision policy, as text.
	Restart string `json:"restart,omitempty"`
}

// WakeSourceMessage is one thing that wakes a declared loop.
// Kind says whether a topic, a period (Every) or a function wakes the loop.
type WakeSourceMessage struct {
	// Kind is one of the Wake constants.
	Kind string `json:"kind"`
	// Every is the period of an interval wake, as a Go duration.
	Every string `json:"every,omitempty"`
	// Topic is the node ID of a topic wake.
	Topic string `json:"topic,omitempty"`
	// Func locates the function computing a deadline wake.
	Func *SourceMessage `json:"func,omitempty"`
}

// SelectCaseMessage is one case of a select statement in a hand-written loop.
// The analyzer reads it from the loop's body; Kind says what the case waits
// on.
type SelectCaseMessage struct {
	// Text is the case as written: "<-ticker.C", "job := <-jobs".
	Text string `json:"text"`
	// Kind is one of the Select constants.
	Kind string `json:"kind"`
	// Source is where the case is.
	Source *SourceMessage `json:"source,omitempty"`
}

// MechanicMessage is a generic building block, backed by an SDK package, that a node
// composes. The catalog lists every mechanic kit offers; an endpoint's
// pipeline lists the ones it uses.
type MechanicMessage struct {
	// Kind is the stable identifier: "validate", "ratelimit", "timeout"…
	Kind string `json:"kind"`
	// Label is a short human rendering of the configuration: "5/s".
	Label string `json:"label"`
	// Package is the SDK package that implements it.
	Package string `json:"package,omitempty"`
	// Doc says what it does, for a catalog.
	Doc string `json:"doc,omitempty"`
	// Snippet is the Go code that adds it, for a catalog.
	Snippet string `json:"snippet,omitempty"`
	// Config is the configuration, as text.
	Config map[string]string `json:"config,omitempty"`
}

// SchemaMessage describes a Go type as it appears on the wire.
// It is a JSON-Schema-like shape: a kind, its fields or elements, and its Go
// type.
type SchemaMessage struct {
	// Type is "object", "array", "map", "string", "integer", "number",
	// "boolean" or "any".
	Type string `json:"type"`
	// Name is the qualified Go type name, for named types.
	Name string `json:"name,omitempty"`
	// Format refines a scalar: "date-time", "duration", "int64"…
	Format string `json:"format,omitempty"`
	// Fields are the members of an object.
	Fields []FieldMessage `json:"fields,omitempty"`
	// Items is the element type of an array.
	Items *SchemaMessage `json:"items,omitempty"`
	// Values is the value type of a map.
	Values *SchemaMessage `json:"values,omitempty"`
	// Enum lists the allowed values, when they are known.
	Enum []string `json:"enum,omitempty"`
	// Ref names a type already described higher up, to break a cycle.
	Ref string `json:"ref,omitempty"`
	// Nullable says a nil value is written null: a pointer, a slice, a map,
	// an interface — unless its member leaves it out (omitempty, omitzero).
	Nullable bool `json:"nullable,omitempty"`
}

// FieldMessage is one member of an object schema.
// It carries the JSON name, the schema of its value and the classes of its
// data.
type FieldMessage struct {
	// Name is the wire name.
	Name string `json:"name"`
	// In is where a request field is read from: "body", "path", "query",
	// "header" or "cookie". Empty outside requests.
	In string `json:"in,omitempty"`
	// Type is the member's schema.
	Type *SchemaMessage `json:"type"`
	// Optional is set when the member may be absent.
	Optional bool `json:"optional,omitempty"`
	// Rules are the validation rules, as written in the validate tag.
	Rules string `json:"rules,omitempty"`
	// Doc is the field's comment, when the analyzer found one.
	Doc string `json:"doc,omitempty"`
	// Class is what the field holds, as its kit tag says (ADR 0006): one of
	// the Class constants, or empty when the field is unclassified. A
	// subject field is personal unless it is special.
	Class string `json:"class,omitempty"`
	// Subject marks the field that says whom a record is about.
	Subject bool `json:"subject,omitempty"`
	// Moderated marks content others see and a moderator may act on.
	Moderated bool `json:"moderated,omitempty"`
	// Sealed is set when kit keeps the field sealed at rest (ADR 0006 §4):
	// a personal, special or secret field, or the subject, not plain, of
	// what kit keeps on disk — a store's entity, a topic's message, a queued
	// command's input. A store in memory seals nothing.
	Sealed bool `json:"sealed,omitempty"`
	// Erased marks the time kit stamps when it erases the record.
	Erased bool `json:"erased,omitempty"`
	// History is how many former values kit keeps of the field (ADR 0007).
	History int `json:"history,omitempty"`
}

// NodeKind is the closed set of building blocks a kit product is made of.
// It is a wire format — the graph's JSON and the Studio's TypeScript unions
// carry these names —, so it stays a string.
type NodeKind string

// BinarySpec is one executable the product ships: the [NodeEntity.Binary] of a
// [KindBinary] node, naming its roles.
type BinarySpec struct {
	// Package is the Go package of its main.
	Package string `json:"package,omitempty"`
	// Roles are the IDs of its process roles, in declaration order; the
	// first is the one it runs with no role argument.
	Roles []string `json:"roles"`
}

// RoleSpec is one process role of a binary: the [NodeEntity.Role] of a
// [KindRole] node — its profile, arguments, singleton and idle stop.
type RoleSpec struct {
	// Binary is the ID of the binary that holds it.
	Binary string `json:"binary"`
	// Profile is one of the Profile constants.
	Profile string `json:"profile"`
	// Args are the leading arguments that select it — ["daemon"] for
	// "statusline daemon" —; empty for the binary's default role.
	Args []string `json:"args,omitempty"`
	// Singleton, when set, is the scope of the lock that keeps one process of
	// this role alive at a time: what the lock's name is derived from.
	Singleton string `json:"singleton,omitempty"`
	// IdleMs is how long a daemon waits without a client before it stops
	// itself; zero means it runs until stopped.
	IdleMs int64 `json:"idleMs,omitempty"`
}

// CLISpec is a short command-line command: the [NodeEntity.CLI] of a [KindCLI]
// node, the words that run it.
type CLISpec struct {
	// Path is the command's words after the binary's name: ["status"],
	// ["daemon", "stop"].
	Path []string `json:"path"`
	// Role is the ID of the role that runs it.
	Role string `json:"role,omitempty"`
}

// ListenerSpec is a listener that is not HTTP: the [NodeEntity.Listener] of a
// [KindListener] node — its network, its contract, who may connect.
type ListenerSpec struct {
	// Network is one of the Network constants.
	Network string `json:"network"`
	// Contract is the versioned contract spoken on it: "render/v1".
	Contract string `json:"contract"`
	// Peer says who may connect: "owner" (the process's own user), or the
	// declared list, never "anyone".
	Peer string `json:"peer"`
	// Role is the ID of the role that runs it.
	Role string `json:"role,omitempty"`
}

// LibrarySpec is a package shared between components (D19): the
// [NodeEntity.Library] of a [KindLibrary] node.
type LibrarySpec struct {
	// Package is its Go import path.
	Package string `json:"package"`
}

// PresentationSpec is what turns results into what a reader sees: the
// [NodeEntity.Presentation] of a [KindPresentation] node.
type PresentationSpec struct {
	// Media is what it renders: "text", "ansi", "html", "json".
	Media string `json:"media"`
}

// PersonalDataMessage is a person's data as kit.Export gives it (GDPR art. 15 and
// 20): their records, store by store, with what art. 15(1) asks beside them.
type PersonalDataMessage struct {
	// Stores are the stores that keep records about the person.
	Stores []StoreDataMessage `json:"stores"`
}

// StoreDataMessage is one store's records about a person.
// It is one part of what kit.Export gives a person about themselves.
type StoreDataMessage struct {
	// Store is the store's node ID.
	Store string `json:"store"`
	// Purpose is why the store keeps them.
	Purpose string `json:"purpose,omitempty"`
	// Retention says, in words, how long they keep their personal data.
	Retention string `json:"retention,omitempty"`
	// Recipients are who inside the product reads them, as far as the
	// running app knows.
	Recipients []string `json:"recipients,omitempty"`
	// Records are the records, their secret members left out. They hold the
	// person's data, which the Studio and the logs never show.
	Records []json.RawMessage `json:"records" kit:"personal"`
	// Former are the former values of the records' fields that keep them
	// (ADR 0007), record by record; a secret field's are left out.
	Former []RecordFormerMessage `json:"former,omitempty" kit:"personal"`
	// Versions are the versions of the records a store with revisions keeps
	// (ADR 0007 §3), record by record, their secret members left out.
	Versions []ExportedVersionsMessage `json:"versions,omitempty" kit:"personal"`
}

// ExportedVersionsMessage are the versions of one exported record, as a
// StoreDataMessage carries them beside its records.
type ExportedVersionsMessage struct {
	// Record is the record's position in its StoreData's Records.
	Record int `json:"record"`
	// Versions are its versions, newest first — the record as it is now
	// first —, each without its secret members.
	Versions []RecordVersionMessage `json:"versions"`
}

// ErasureMessage is what kit.Erase did, store by store.
// Stores lists, store by store, what the erasure did there.
type ErasureMessage struct {
	// Stores are the stores that kept records about the person.
	Stores []StoreErasureMessage `json:"stores"`
}

// StoreErasureMessage is one store's part of an erasure: the keys of the records
// erased, deleted, and held — left in place, as a legal hold asks. A key
// may be personal data, which the Studio and the logs never show.
type StoreErasureMessage struct {
	// Store is the store's node ID.
	Store string `json:"store"`
	// Erased are the records whose personal data was cleared.
	Erased []string `json:"erased,omitempty" kit:"personal"`
	// Deleted are the records removed.
	Deleted []string `json:"deleted,omitempty" kit:"personal"`
	// Held are the records a hold keeps, untouched.
	Held []string `json:"held,omitempty" kit:"personal"`
}

// PrivacyMessage is what a running app says of the personal data it keeps.
// It is the Privacy page's data: the register, the holds and the journal's
// state.
type PrivacyMessage struct {
	// Retention is KIT_RETENTION: one of the Retention constants.
	Retention string `json:"retention"`
	// Register is the record of processing, as far as the code knows it.
	Register RegisterMessage `json:"register"`
	// Holds are the records a legal hold keeps, newest first.
	Holds []HoldEvent `json:"holds,omitempty"`
	// Journal is the privacy journal's latest entries, newest first.
	Journal []JournalEntryEvent `json:"journal,omitempty"`
	// Chain says whether the journal's chain holds.
	Chain JournalCheckMessage `json:"chain"`
}

// RegisterMessage is the record of processing of GDPR art. 30(1), as far as the
// code knows it.
type RegisterMessage struct {
	// App is the product.
	App string `json:"app"`
	// ToComplete are the points the code cannot know, for a person to
	// write: "a" (the controller and its representatives), "e" (the
	// transfers).
	ToComplete []string `json:"toComplete,omitempty"`
	// Stores are the stores that keep personal data, by node ID.
	Stores []RegisterStoreMessage `json:"stores,omitempty"`
}

// RegisterStoreMessage is one store's line in the register.
// It names the classes the store keeps, their purposes and their retention.
type RegisterStoreMessage struct {
	// Store is the store's node ID.
	Store string `json:"store"`
	// Purpose is point (b): why the store keeps its records.
	Purpose string `json:"purpose,omitempty"`
	// Subject is point (c)'s category of data subjects: the pointer of the
	// field that says whom each record is about.
	Subject string `json:"subject,omitempty"`
	// SubjectDoc is that field's comment, when the analyzer read it.
	SubjectDoc string `json:"subjectDoc,omitempty"`
	// Personal, Special and Secret are point (c)'s categories of personal
	// data: the fields of each class, as JSON pointers. Special fields are
	// art. 9 data; secret ones are credentials.
	Personal []string `json:"personal,omitempty"`
	Special  []string `json:"special,omitempty"`
	Secret   []string `json:"secret,omitempty"`
	// Recipients are point (d) inside the product: the nodes the graph
	// shows reading the store, and the connectors that carry its data out.
	Recipients []string `json:"recipients,omitempty"`
	// Erase, Delete and HeldUntil are point (f), the time limits, in words.
	Erase     string `json:"erase,omitempty"`
	Delete    string `json:"delete,omitempty"`
	HeldUntil string `json:"heldUntil,omitempty"`
	// ByProduct is point (f) when the product keeps the store's retention
	// itself (kit.RetentionByProduct), in its own words: no retention gap,
	// and no subject gap either.
	ByProduct *ProductRetentionSpec `json:"byProduct,omitempty"`
	// Security is point (g): the measures kit takes.
	Security []string `json:"security,omitempty"`
	// Gaps are the Gap constants the store lacks.
	Gaps []string `json:"gaps,omitempty"`
}

// HoldEvent is one record a legal hold keeps. It carries references only: never
// the record's key, its subject's identity, or the hold's reason, which kit
// keeps apart.
type HoldEvent struct {
	// Store is the store's node ID.
	Store string `json:"store"`
	// Record is the record's reference.
	Record string `json:"record"`
	// Subject is the reference of the person the record is about, when it
	// has one.
	Subject string `json:"subject,omitempty"`
	// By is who placed it: a user's ID, "cli" or "studio".
	By string `json:"by"`
	// At is when.
	At time.Time `json:"at"`
}

// JournalEntryEvent is one operation of the privacy journal: what was done,
// where, by whom and when, with references only — never an identity, a
// value or a key. Each entry is chained to the previous one by SHA-256.
type JournalEntryEvent struct {
	// Seq numbers the entries from 1, with no gap.
	Seq int64 `json:"seq"`
	// At is when, on the app's clock.
	At time.Time `json:"at"`
	// Op is one of the Journal constants.
	Op string `json:"op"`
	// DryRun marks what the retention would have done under
	// KIT_RETENTION=dry-run: nothing changed.
	DryRun bool `json:"dryRun,omitempty"`
	// Store is the store's node ID.
	Store string `json:"store,omitempty"`
	// Record is the record's reference; Subject its subject's.
	Record  string `json:"record,omitempty"`
	Subject string `json:"subject,omitempty"`
	// By is who: a user's ID, the node that called, "retention", "cli" or
	// "studio".
	By string `json:"by"`
	// Hash is the entry's link in the chain: SHA-256 of the previous
	// entry's hash and this entry.
	Hash string `json:"hash"`
}

// JournalCheckMessage is what verifying the journal's chain found.
// A broken chain names the first entry whose hash does not follow.
type JournalCheckMessage struct {
	// Entries is how many entries the journal holds.
	Entries int `json:"entries"`
	// BrokenAt is the sequence number where the chain breaks: an entry
	// changed, or one removed before it. Zero when the chain holds.
	BrokenAt int64 `json:"brokenAt,omitempty"`
}

// RecordFormerMessage is the former values of one exported record's fields.
// A personal or special field's former values are redacted, never exported in
// clear.
type RecordFormerMessage struct {
	// Record is the record's position in its StoreData's Records.
	Record int `json:"record"`
	// Fields are each field's former values, newest first, by the field's
	// JSON pointer. A secret field's are left out.
	Fields map[string][]FormerMessage `json:"fields"`
}

// ProfileResult is a pprof profile of the running product, folded onto its graph:
// every sample is attributed to the node whose code was running — through
// the pprof label kit puts on every handler, subscription, job and loop run,
// or, for the heap, which carries no label, through the node's code functions
// on the sample's stack.
type ProfileResult struct {
	// Kind is one of the Profile constants.
	Kind string `json:"kind"`
	// At is when the profile ended.
	At time.Time `json:"at"`
	// DurationMs is how long a CPU profile sampled.
	DurationMs float64 `json:"durationMs,omitempty"`
	// Unit is what the values count: "ms" of CPU, "bytes" of heap.
	Unit string `json:"unit"`
	// Total is the sum of every sample.
	Total float64 `json:"total"`
	// Nodes are the costs attributed to nodes, highest first.
	Nodes []NodeCostMessage `json:"nodes"`
	// Unattributed is the cost outside any node's code: the runtime, the
	// garbage collector, kit itself, idle loops.
	Unattributed float64 `json:"unattributed"`
	// Top are the costliest functions, by flat cost.
	Top []FuncCostMessage `json:"top"`
	// Flame is the call tree, root first, pruned below 0.5% of Total.
	Flame *FlameNodeMessage `json:"flame,omitempty"`
}

// NodeCostMessage is what one node cost.
// It is the share of the profile's samples spent in the node's code.
type NodeCostMessage struct {
	// Node is the node ID.
	Node string `json:"node"`
	// Value is the cost, in the profile's unit.
	Value float64 `json:"value"`
	// Share is Value over Total, from 0 to 1.
	Share float64 `json:"share"`
	// Top are the node's costliest functions.
	Top []FuncCostMessage `json:"top,omitempty"`
}

// FuncCostMessage is what one function cost.
// It carries the flat and cumulative samples of the function and where it
// lives.
type FuncCostMessage struct {
	// Func is the qualified function name.
	Func string `json:"func"`
	// Source locates it, when it is in the product's module.
	Source *SourceMessage `json:"source,omitempty"`
	// Flat is the cost of the function's own code; Cum includes its callees.
	Flat float64 `json:"flat"`
	Cum  float64 `json:"cum"`
	// Node is the node it was attributed to, when one.
	Node string `json:"node,omitempty"`
}

// FlameNodeMessage is one frame of a flame graph.
// Its children are the frames it called; its value is the samples under it.
type FlameNodeMessage struct {
	// Name is the function.
	Name string `json:"name"`
	// Value is its cumulative cost.
	Value float64 `json:"value"`
	// Node is the node the frame belongs to, when it is a node's code.
	Node string `json:"node,omitempty"`
	// Children are its callees, highest first.
	Children []*FlameNodeMessage `json:"children,omitempty"`
}

// GoroutinesResult is every goroutine of the process, grouped by what it runs.
// Each group names the node its stack runs in, when one does.
type GoroutinesResult struct {
	// At is when they were counted.
	At time.Time `json:"at"`
	// Total is how many goroutines exist.
	Total int `json:"total"`
	// Groups are goroutines sharing a node or loop, a state and a top frame,
	// largest first.
	Groups []GoroutineGroup `json:"groups"`
}

// GoroutineGroup is goroutines doing the same thing.
// They share one stack; Count says how many run it.
type GoroutineGroup struct {
	// Node is the node they run for, from their pprof label, when any.
	Node string `json:"node,omitempty"`
	// Loop is the loop they are, when kit knows: "http accept", a consumer.
	Loop string `json:"loop,omitempty"`
	// State is the runtime's word for what they wait on: "running",
	// "select", "chan receive", "IO wait", "sleep", "semacquire"…
	State string `json:"state"`
	// Count is how many goroutines are in the group.
	Count int `json:"count"`
	// Top is the innermost frame that is not the runtime's.
	Top string `json:"top"`
	// Stack is the group's stack, innermost first, capped.
	Stack []string `json:"stack,omitempty"`
}

// RuntimeMessage is what a running process says about itself: the daemon's own state
// and its internal loop.
type RuntimeMessage struct {
	// Phase is one of the Phase constants.
	Phase string `json:"phase"`
	// StartedAt is when the process started.
	StartedAt time.Time `json:"startedAt"`
	// Components are the lifecycle components, in start order.
	Components []ComponentMessage `json:"components"`
	// Loops are the recurring pieces of the internal loop.
	Loops []LoopMessage `json:"loops"`
	// History lists the phases the process went through, oldest first: the
	// daemon's own state machine, as it ran.
	History []PhaseChangeEvent `json:"history,omitempty"`
	// Process is the Go process, sampled when the graph was built.
	Process *ProcessSpec `json:"process,omitempty"`
	// HTTP is the product's HTTP server.
	HTTP *HTTPServer `json:"http,omitempty"`
	// Mocks are the replacements a test gave the app (kit.Replace).
	Mocks []MockMessage `json:"mocks,omitempty"`
	// Dev describes the build `kit dev` made of this process, when it did.
	Dev *DevBuildMessage `json:"dev,omitempty"`
	// Config is how the product was configured when it started: every
	// setting kit read, the value it uses — never a secret's — and where
	// that value came from.
	Config []SettingMessage `json:"config,omitempty"`
	// Boot is what kit did to start the product, step by step, as it ran;
	// the lifecycle components it then started are Components.
	Boot []BootStepMessage `json:"boot,omitempty"`
	// Databases are the databases the app declares, as this run found them:
	// each one's state, readiness, pool and migrations.
	Databases []DatabaseMessage `json:"databases,omitempty"`
}

// DatabaseMessage is one database the app declares (kit.Database), as the running
// process found it. Its URL is never shown: where it was found, the engine,
// the address and the TLS mode are.
type DatabaseMessage struct {
	// Name is the database's, as the app declares it.
	Name string `json:"name"`
	// Engine is the engine it runs on: "postgres", "mysql", "sqlite".
	Engine string `json:"engine"`
	// State is one of the Database constants.
	State string `json:"state"`
	// Ready says whether it answered its last check; CheckedAt says when.
	Ready     bool       `json:"ready"`
	CheckedAt *time.Time `json:"checkedAt,omitempty"`
	// Problem is the public text of its last failure: a start that failed,
	// a check it did not answer.
	Problem string `json:"problem,omitempty"`
	// URLFrom is where its URL was found — a Setting constant: env, store,
	// or default for a SQLite file beside the data —, empty when it is set
	// nowhere.
	URLFrom string `json:"urlFrom,omitempty"`
	// TLS is the TLS mode its URL writes: "verify-full"; "none" when it is
	// written off; empty when the URL leaves it to the driver, or when the
	// database is a file.
	TLS string `json:"tls,omitempty"`
	// Pool is database/sql's own count of its connections, sampled when the
	// graph was built.
	Pool *Pool `json:"pool,omitempty"`
	// Migrations are its sets of migrations, kit's first, as the start —
	// or the last sample — found them.
	Migrations []MigrationSetMessage `json:"migrations,omitempty"`
}

// Pool is a database's connection pool, as database/sql counts it.
// It is sampled when the runtime state is read; its counters never move a
// revision.
type Pool struct {
	// MaxOpen is its ceiling.
	MaxOpen int `json:"maxOpen"`
	// Open is how many connections are open: InUse and Idle.
	Open  int `json:"open"`
	InUse int `json:"inUse"`
	Idle  int `json:"idle"`
	// Waits counts the calls that waited for a connection, and WaitMs how
	// long they waited in all.
	Waits  int64   `json:"waits"`
	WaitMs float64 `json:"waitMs"`
	// Closed counts the connections closed for being idle too many, idle
	// too long, or too old.
	Closed int64 `json:"closed,omitempty"`
}

// MigrationSetMessage is one set of migrations on a database — kit's own, the
// product's (kit.Migrations), a module's — with its own version table, and
// so its own lock.
type MigrationSetMessage struct {
	// Name is the set's origin: "kit", "product", or a module's name.
	Name string `json:"name"`
	// Table is its version table: "kit_migrations", "schema_migrations".
	Table string `json:"table"`
	// Applied are the migrations the database records, and Pending those
	// this build carries that it does not, oldest first.
	Applied []MigrationMessage `json:"applied,omitempty"`
	Pending []MigrationMessage `json:"pending,omitempty"`
	// Problem is why the set could not be read or applied.
	Problem string `json:"problem,omitempty"`
}

// MigrationMessage is one versioned migration.
// Its Version orders it among the others; Name says what it does.
type MigrationMessage struct {
	// Version orders it: a UTC timestamp by convention, 20260910143000.
	Version uint64 `json:"version"`
	// Name says what it does; empty for a version this build does not carry.
	Name string `json:"name,omitempty"`
}

// SettingMessage is one configuration value kit read when the product started:
// kit's own, or one a service of the product declares.
type SettingMessage struct {
	// Name is the environment variable that sets it: "KIT_ADDR",
	// "TODO_BASE_URL".
	Name string `json:"name"`
	// Value is what kit uses. A secret's is left out: Secret says so.
	Value string `json:"value,omitempty"`
	// From is one of the Setting constants.
	From string `json:"from"`
	// Service declared it; empty for kit's own.
	Service string `json:"service,omitempty"`
	// Key is a declared setting's name, its key in a configuration file:
	// "base-url". A module's is qualified with the module's name,
	// "moderation.tdb-url": kit.Set's key, and in a file "tdb-url" under
	// "moderation:" (ADR 0008).
	Key string `json:"key,omitempty"`
	// Type is what a declared setting holds: text, bool, int, number,
	// duration or list.
	Type string `json:"type,omitempty"`
	// Detail is the configuration file that gave the value, when From is
	// SettingFile: "config/production.yaml".
	Detail string `json:"detail,omitempty"`
	// Secret: the value is withheld.
	Secret bool `json:"secret,omitempty"`
	// Option is the AppOption that sets it in code, when there is one:
	// "kit.Listen". Code wins over the environment.
	Option string `json:"option,omitempty"`
	// Flag is the kit dev flag that sets it in dev, when there is one:
	// "-addr".
	Flag string `json:"flag,omitempty"`
	// Database is the database the setting configures, when kit declares it
	// for one (kit.Database): its URL, its pool, its timeouts.
	Database string `json:"database,omitempty"`
}

// BootStepMessage is one step of the start, as it ran.
// It carries when it began, how long it took and, when it failed, its error.
type BootStepMessage struct {
	// Name is one of the Boot constants.
	Name string `json:"name"`
	// Count is how many it went through: settings, warnings, services,
	// routes, components.
	Count int `json:"count,omitempty"`
	// Value is what it used: the data directory, in dev.
	Value string `json:"value,omitempty"`
	// Begun is when it began.
	Begun time.Time `json:"begun"`
	// TookMs is how long it took.
	TookMs float64 `json:"tookMs"`
	// Error is the public message of a failure.
	Error string `json:"error,omitempty"`
}

// DevBuildMessage is one build of `kit dev`: when, how long, and why.
// It lets the Studio say what changed and how long the reload took.
type DevBuildMessage struct {
	// BuiltAt is when the build finished.
	BuiltAt *time.Time `json:"builtAt,omitempty"`
	// BuildMs is how long it took.
	BuildMs float64 `json:"buildMs,omitempty"`
	// Rebuilds counts the builds of this kit dev session, this one
	// included: 1 is the first start.
	Rebuilds int `json:"rebuilds,omitempty"`
	// Changed are the files whose change triggered this build, relative to
	// the module root, at most 20.
	Changed []string `json:"changed,omitempty"`
	// More counts the changed files beyond Changed.
	More int `json:"more,omitempty"`
}

// PhaseChangeEvent is one step of the daemon's life.
// It carries the phase entered, when it was entered, and why.
type PhaseChangeEvent struct {
	// Phase is the phase entered: one of the Phase constants.
	Phase string `json:"phase"`
	// At is when.
	At time.Time `json:"at"`
	// Reason says why, when it is not the natural next step: "SIGTERM",
	// "a component failed".
	Reason string `json:"reason,omitempty"`
}

// ProcessSpec is the Go process a product runs in.
// It carries the runtime's figures — goroutines, heap, GC, CPU — taken at At.
type ProcessSpec struct {
	// PID is the process ID.
	PID int `json:"pid"`
	// Go is the Go version the binary was built with.
	Go string `json:"go"`
	// OS and Arch are GOOS and GOARCH.
	OS   string `json:"os"`
	Arch string `json:"arch"`
	// MaxProcs is GOMAXPROCS; CPUs the logical CPUs the process sees.
	MaxProcs int `json:"maxProcs"`
	CPUs     int `json:"cpus"`
	// Goroutines is how many goroutines exist.
	Goroutines int `json:"goroutines"`
	// HeapBytes is the live heap; HeapObjects its object count.
	HeapBytes   uint64 `json:"heapBytes"`
	HeapObjects uint64 `json:"heapObjects"`
	// HeapGoalBytes is the heap size at which the next collection starts.
	HeapGoalBytes uint64 `json:"heapGoalBytes,omitempty"`
	// MemoryBytes is all the memory the Go runtime holds from the system:
	// the heap, the stacks, the runtime's own structures.
	MemoryBytes uint64 `json:"memoryBytes,omitempty"`
	// TotalAllocBytes is every byte ever allocated on the heap.
	TotalAllocBytes uint64 `json:"totalAllocBytes"`
	// GCCycles counts completed garbage collections.
	GCCycles uint64 `json:"gcCycles"`
	// LastGC is when the last collection ended; absent before the first.
	LastGC *time.Time `json:"lastGC,omitempty"`
	// GCPauseP99Ms is the 99th percentile stop-the-world pause.
	GCPauseP99Ms float64 `json:"gcPauseP99Ms"`
	// SchedLatencyP99Ms is the 99th percentile time a goroutine waited to run.
	SchedLatencyP99Ms float64 `json:"schedLatencyP99Ms"`
	// CPUSeconds is the CPU time the process consumed, user and system.
	CPUSeconds float64 `json:"cpuSeconds"`
	// UptimeMs is how long the process has run.
	UptimeMs float64 `json:"uptimeMs"`
	// At is when the sample was taken.
	At time.Time `json:"at"`
}

// HTTPServer is the product's HTTP server, and whose loop serves it.
// Its address is the one it listens on; its loop is the node that runs it.
type HTTPServer struct {
	// Library is the implementation: "sdk/v1/net/server" — the SDK's engine
	// accepting and draining the connections, net/http speaking the protocol.
	Library string `json:"library"`
	// Loop says how it serves: one accept loop, one goroutine per
	// connection, written by the library rather than the product.
	Loop string `json:"loop"`
	// Addr is the listening address.
	Addr string `json:"addr,omitempty"`
	// Middleware is the chain every request goes through before its route,
	// outermost first.
	Middleware []MechanicMessage `json:"middleware,omitempty"`
	// Timeouts are the server's timeouts, as Go durations: "readHeader",
	// "read", "write", "idle".
	Timeouts map[string]string `json:"timeouts,omitempty"`
	// Conns counts connections: "active" now, "total" ever accepted,
	// "rejected" by the listener's ceiling. Older graphs carry "new", "idle"
	// and "hijacked" too.
	Conns map[string]int64 `json:"conns,omitempty"`
	// InFlight is how many requests are being served.
	InFlight int64 `json:"inFlight"`
	// Served counts the requests served since start.
	Served int64 `json:"served"`
}

// ComponentMessage is one lifecycle component: brought up in order, taken down in
// reverse.
type ComponentMessage struct {
	// Name is the lifecycle name: "store:todos/store/todos", "http"…
	Name string `json:"name"`
	// Node is the node the component belongs to, when there is one.
	Node string `json:"node,omitempty"`
	// State is one of the Component constants.
	State string `json:"state"`
	// Begun is when the last start or stop call began.
	Begun *time.Time `json:"begun,omitempty"`
	// TookMs is how long that call took.
	TookMs float64 `json:"tookMs,omitempty"`
	// Error is the public message of a failure.
	Error string `json:"error,omitempty"`
}

// LoopMessage is one recurring piece of the daemon's internal loop: a job, a
// workflow's timer sweep, a subscription's consumer, the HTTP accept loop, a
// declared or hand-written loop.
type LoopMessage struct {
	// Name identifies the loop.
	Name string `json:"name"`
	// Node is the node the loop drives.
	Node string `json:"node,omitempty"`
	// Kind is one of the Loop constants.
	Kind string `json:"kind"`
	// Provenance is one of the Provenance constants.
	Provenance string `json:"provenance,omitempty"`
	// Library names the code that loops, for a library or kit loop:
	// "net/http", "sdk/v1/app/scheduler", "sdk/v1/data/queue",
	// "sdk/v1/app/mail/spool", "sdk/v1/app/statemachine", "kit".
	Library string `json:"library,omitempty"`
	// State is one of the Loop state constants.
	State string `json:"state,omitempty"`
	// LastWake is why the last run started: "interval", "topic",
	// "deadline", "manual", "start".
	LastWake string `json:"lastWake,omitempty"`
	// Restarts counts supervised restarts, for a hand-written loop.
	Restarts int64 `json:"restarts,omitempty"`
	// Schedule is human text: "every 10s", "*/5 * * * *", "on publish · poll 5s".
	Schedule string `json:"schedule"`
	// Runs counts completed runs.
	Runs int64 `json:"runs"`
	// Errors counts failed runs.
	Errors int64 `json:"errors"`
	// Missed counts due instants dropped because they had already passed.
	Missed int64 `json:"missed"`
	// Skipped counts fires skipped because the previous run was still going.
	Skipped int64 `json:"skipped"`
	// LastRun is when the last run started.
	LastRun *time.Time `json:"lastRun,omitempty"`
	// LastMs is how long the last run took.
	LastMs float64 `json:"lastMs,omitempty"`
	// NextRun is when the next run is due, when it is known.
	NextRun *time.Time `json:"nextRun,omitempty"`
	// LastError is the public message of the last failure.
	LastError string `json:"lastError,omitempty"`
}

// Event is one live event. Exactly one of the payload fields matching Type is
// set.
type Event struct {
	// Seq increases strictly on one stream; a reader drops what it has seen.
	Seq uint64 `json:"seq"`
	// Type selects the payload.
	Type EventType `json:"type"`
	// Time is when it happened.
	Time time.Time `json:"time"`
	// Revision is the graph revision, on hello and graph events.
	Revision string `json:"revision,omitempty"`
	// StartedAt is when the process's current run started, on hello: a new
	// value means the process restarted, and what the reader knew of the
	// previous run is stale.
	StartedAt *time.Time `json:"startedAt,omitempty"`
	// Phase is the process phase, on hello and lifecycle events.
	Phase      string              `json:"phase,omitempty"`
	Span       *SpanMessage        `json:"span,omitempty"`
	Transition *TransitionEvent    `json:"transition,omitempty"`
	Lifecycle  *ComponentMessage   `json:"lifecycle,omitempty"`
	Loop       *LoopMessage        `json:"loop,omitempty"`
	Census     *CensusMessage      `json:"census,omitempty"`
	Log        *LogRecordMessage   `json:"log,omitempty"`
	Mail       *MailSummaryMessage `json:"mail,omitempty"`
}

// SpanMessage is a finished unit of work, attributed to a node. Only allow-listed,
// wire-safe fields travel: no URL, no query string, no private error text.
type SpanMessage struct {
	// TraceID groups the spans of one causal chain (W3C, hex).
	TraceID string `json:"traceId"`
	// SpanID identifies the span (W3C, hex).
	SpanID string `json:"spanId"`
	// ParentID is the parent span, absent on a root.
	ParentID string `json:"parentId,omitempty"`
	// Node is where the work happened.
	Node string `json:"node"`
	// From is the node that caused it: the edge this span travelled.
	From string `json:"from,omitempty"`
	// Edge is the kind of the edge From → Node.
	Edge EdgeKind `json:"edge,omitempty"`
	// Label refines Edge, like the edge's own label.
	Label string `json:"label,omitempty"`
	// Op is one of the Op constants.
	Op string `json:"op"`
	// Name is a low-cardinality operation name: a route pattern, "Get".
	Name string `json:"name"`
	// Start is when the work began.
	Start time.Time `json:"start"`
	// Ms is how long it took.
	Ms float64 `json:"ms"`
	// Status is StatusError when the product failed — what kit answers with
	// a 5xx — and StatusOK otherwise, a refusal the caller has to fix (not
	// found, invalid, conflict, rate limited…) included.
	Status string `json:"status"`
	// Code is the error code, when the work ended in one: a failure's, or a
	// refusal's ("not_found").
	Code string `json:"code,omitempty"`
	// Error is the wire-safe public message of a failure; a refusal has none.
	Error string `json:"error,omitempty"`
	// Attrs are allow-listed attributes: "http.status", "instance"…
	Attrs map[string]string `json:"attrs,omitempty"`
	// User is the authenticated caller's ID, when there is one.
	User string `json:"user,omitempty"`
	// Payload is what went in and out, in dev only, with secrets redacted.
	Payload *Payload `json:"payload,omitempty"`
}

// Payload is the request and the response of a span, as JSON, in dev only.
// Every member whose name says it is a secret — password, token, secret,
// authorization, cookie… — or whose Go field is tagged kit:"secret" is
// replaced by "[redacted]", and each side is cut at 8 KiB.
type Payload struct {
	// Request is the decoded request, or the message delivered.
	Request json.RawMessage `json:"request,omitempty"`
	// Response is the response.
	Response json.RawMessage `json:"response,omitempty"`
	// Truncated is set when a side was cut.
	Truncated bool `json:"truncated,omitempty"`
}

// TransitionEvent is one workflow instance moving between states.
// It names the workflow, the entity, the event and the states it went from
// and to.
type TransitionEvent struct {
	// Workflow is the workflow node ID.
	Workflow string `json:"workflow"`
	// Instance is the entity key.
	Instance string `json:"instance"`
	// Event is the transition's event name.
	Event string `json:"event"`
	// From is the state left; empty on creation.
	From string `json:"from"`
	// To is the state entered.
	To string `json:"to"`
	// Trigger is one of the Trigger constants.
	Trigger string `json:"trigger"`
	// Caller is the node that fired it, when code did.
	Caller string `json:"caller,omitempty"`
}

// CensusMessage is a workflow's population per state.
// It counts the instances in each state when the census was taken.
type CensusMessage struct {
	// Workflow is the workflow node ID.
	Workflow string `json:"workflow"`
	// Counts maps each state to its number of instances.
	Counts map[string]int `json:"counts"`
}

// TraceMessage is the spans sharing one trace ID, root first.
// The root span is the one with no parent in the trace; the others follow it.
type TraceMessage struct {
	// TraceID identifies the trace.
	TraceID string `json:"traceId"`
	// Root is the node of the root span.
	Root string `json:"root"`
	// Name is the root span's name.
	Name string `json:"name"`
	// Start is when the root began.
	Start time.Time `json:"start"`
	// Ms spans from the first start to the last end.
	Ms float64 `json:"ms"`
	// Status is StatusError when any span failed.
	Status string `json:"status"`
	// Spans are in start order.
	Spans []SpanMessage `json:"spans"`
}

// SnippetMessage is source code served to a reader of the graph.
// Focus and FocusEnd mark the lines a reader asked for, inside the lines
// served.
type SnippetMessage struct {
	// File is relative to App.Root.
	File string `json:"file"`
	// StartLine is the 1-based line of Lines[0].
	StartLine int `json:"startLine"`
	// Focus is the first line of the range asked for.
	Focus int `json:"focus"`
	// FocusEnd is the last line of the range asked for.
	FocusEnd int `json:"focusEnd,omitempty"`
	// Lines are the file's lines around the focus, without terminators.
	Lines []string `json:"lines"`
	// Language is the highlighter language: "go", "javascript"…
	Language string `json:"language"`
}

// InstanceMessage is one entity's journey through a workflow.
// It carries the entity's key, its current state and the steps that brought
// it there.
type InstanceMessage struct {
	// ID is the entity key.
	ID string `json:"id"`
	// State is the current state.
	State string `json:"state"`
	// EnteredAt is when the instance entered its current state.
	EnteredAt time.Time `json:"enteredAt"`
	// History lists the transitions, oldest first, capped.
	History []StepEvent `json:"history,omitempty"`
}

// StepEvent is one transition in an instance's history.
// It carries the event, the states it went from and to, and when it fired.
type StepEvent struct {
	// Event is the transition's event name.
	Event string `json:"event"`
	// From is the state left.
	From string `json:"from"`
	// To is the state entered.
	To string `json:"to"`
	// At is when it happened.
	At time.Time `json:"at"`
	// Trigger is one of the Trigger constants.
	Trigger string `json:"trigger"`
	// Caller is the node that fired it, when code did.
	Caller string `json:"caller,omitempty"`
}

// LogRecordMessage is one log record written by product code through kit.Log, kept
// in dev so the Studio can show a request's logs beside its spans.
type LogRecordMessage struct {
	// Seq orders records; it only increases.
	Seq uint64 `json:"seq"`
	// Time is when it was written.
	Time time.Time `json:"time"`
	// Level is "debug", "info", "warn" or "error".
	Level string `json:"level"`
	// Message is the record's message.
	Message string `json:"message"`
	// Node is the node whose code wrote it.
	Node string `json:"node,omitempty"`
	// TraceID and SpanID correlate it with a span.
	TraceID string `json:"traceId,omitempty"`
	SpanID  string `json:"spanId,omitempty"`
	// Attrs are the record's attributes, as text, secrets redacted.
	Attrs map[string]string `json:"attrs,omitempty"`
}

// MockMessage is the replacement a test gave the app ([MockReplace]).
// It is set by a test only; the Studio shows it and never sets one (D13).
type MockMessage struct {
	// Node is the node it applies to: a port, a command or a query.
	Node string `json:"node"`
	// Mode is [MockReplace].
	Mode string `json:"mode"`
	// Hits counts the runs it changed.
	Hits int64 `json:"hits"`
}

// MailSummaryMessage is one mail as the outbox sees it.
// It carries no body: the Studio lists summaries and reads a whole mail on
// demand.
type MailSummaryMessage struct {
	// ID identifies the mail in the outbox.
	ID string `json:"id"`
	// Mailer is the mailer node.
	Mailer string `json:"mailer"`
	// From and To are addresses, rendered.
	From string   `json:"from"`
	To   []string `json:"to"`
	// Subject is the subject.
	Subject string `json:"subject"`
	// Status is one of the Mail constants.
	Status string `json:"status"`
	// Attempts counts delivery attempts.
	Attempts int `json:"attempts"`
	// Error is the public message of the last failure.
	Error string `json:"error,omitempty"`
	// QueuedAt is when it entered the outbox; SentAt when it left.
	QueuedAt time.Time  `json:"queuedAt"`
	SentAt   *time.Time `json:"sentAt,omitempty"`
	// TraceID is the trace that queued it.
	TraceID string `json:"traceId,omitempty"`
	// Node is the node that queued it.
	Node string `json:"node,omitempty"`
}

// IsEngine reports whether backend names an engine a database runs on.
func IsEngine(backend string) bool {
	return isEngine(backend)
}

// NodeID builds the ID of a node declared in a service. A service's own ID is
// its name.
func NodeID(service string, kind NodeKind, name string) string {
	return nodeID(service, kind, name)
}

// EdgeID builds the ID of an edge. The label is part of the identity: two
// transitions of one workflow fired from one endpoint are two edges.
func EdgeID(from string, kind EdgeKind, to, label string) string {
	return edgeID(from, kind, to, label)
}

// BinaryID is the ID of a binary.
func BinaryID(binary string) string {
	return binaryID(binary)
}

// RoleID is the ID of one process role of a binary.
func RoleID(binary, role string) string {
	return roleID(binary, role)
}

// LibraryID is the ID of a library.
func LibraryID(library string) string {
	return libraryID(library)
}

// ModulePrefix is a module's default mount prefix: "/<name>/".
func ModulePrefix(name string) string {
	return modulePrefix(name)
}

// UnderPrefix is a route declared at path, served under a module's mount
// prefix: "/reports" under "/moderation/" is "/moderation/reports", and
// under "/" it stays "/reports".
func UnderPrefix(prefix, path string) string {
	return underPrefix(prefix, path)
}
